    "usageCode": "import { GlobeArcs } from \"@/components/ui/GlobeArcs\";\n\nexport function Example() {\n  return (\n    <div className=\"w-full\">\n      <GlobeArcs autoRotateSpeed={0.004} />\n    </div>\n  );\n}",
    "cliCommand": "npx shadcn@latest add https://boseui.site/r/globe-arcs.json",
