    "usageCode": "import { StickyScrollStory } from \"@/components/ui/sticky-scroll-story\";\n\nexport function Example() {\n  return <StickyScrollStory />;\n}",
    "cliCommand": "npx shadcn@latest add https://boseui.site/r/sticky-scroll-story.json",
